static xts_state_t in, out;

static int x_vd(uint32_t w) { return (int)(((w >> 21) & 31) | ((w >> 2) & 3) << 5); }

static int replay(const hw_rec_t *r)
{
  xts_mem_t m;
  xts_state_baseline(&in);
  in.vscr.w[3] = r->vscr;
  for (int i = 0; i < r->nregs; i++) memcpy(in.vr[r->reg[i].r].w, r->reg[i].v, sizeof r->reg[i].v);
  xts_mem_init(&m);
  if (xts_model_exec(NULL, r->word, &in, &m, &out) != XTS_M_OK) return 0;
  return memcmp(out.vr[x_vd(r->word)].w, r->vd, sizeof r->vd) == 0 && out.vscr.w[3] == r->vscr;
}

static void replay_all(const char *mnem, int want)
{
  int n = 0, ok = 0;
  for (size_t i = 0; i < sizeof RECS / sizeof RECS[0]; i++) {
    const hw_rec_t *r = &RECS[i];
    if (strncmp(r->id, mnem, strlen(mnem)) != 0) continue;
    n++;
    if (replay(r)) ok++;
    else {
      const uint32_t *g = out.vr[x_vd(r->word)].w;
      printf("    %s %08X: model %08X%08X%08X%08X vscr %08X, cpu %08X%08X%08X%08X vscr %08X\n", r->id, r->word, g[0],
             g[1], g[2], g[3], out.vscr.w[3], r->vd[0], r->vd[1], r->vd[2], r->vd[3], r->vscr);
    }
  }
  HT_EQ_U64(n, want);
  HT_EQ_U64(ok, n);
}

HTEST(hw_sem_vmsum3fp128) { replay_all("vmsum3fp128", 68); }
HTEST(hw_sem_vmsum4fp128) { replay_all("vmsum4fp128", 83); }
HTEST(hw_sem_vpkd3d128) { replay_all("vpkd3d128", 48); }
